import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.B7YvHKtj.js";const p=JSON.parse('{"title":"OpenRouter 云端模型配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/providers/openrouter.md","filePath":"zh/docs/providers/openrouter.md"}'),a={name:"zh/docs/providers/openrouter.md"};function n(i,e,s,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="openrouter-云端模型配置指南" tabindex="-1">OpenRouter 云端模型配置指南 <a class="header-anchor" href="#openrouter-云端模型配置指南" aria-label="Permalink to &quot;OpenRouter 云端模型配置指南&quot;">​</a></h1><p><strong>OpenRouter</strong> 是目前最方便的统一云端 AI 网关。它聚合了全球 200+ 顶尖大语言模型（包括 DeepSeek V3、Gemini 2.5 Flash、Claude 3.5 Haiku、GPT-4o 等）。</p><p>如果你使用的是轻薄本、没有独立显卡，或者希望获得专业文学级的字幕翻译水准，推荐使用 OpenRouter。</p><hr><h2 id="_1-获取-openrouter-api-key" tabindex="-1">1. 获取 OpenRouter API Key <a class="header-anchor" href="#_1-获取-openrouter-api-key" aria-label="Permalink to &quot;1. 获取 OpenRouter API Key&quot;">​</a></h2><ol><li>前往 <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">OpenRouter 官网</a> 注册账号。</li><li>访问 <a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">Keys 管理页面</a>，点击 <strong>Create Key</strong> 生成一个新的 API 密钥。</li><li>复制生成的密钥（格式通常为 <code>sk-or-v1-...</code>）。</li><li>（可选）为账户充值少量余额（如 $5 即可翻译几十部整季剧集）。</li></ol><hr><h2 id="_2-推荐模型搭配" tabindex="-1">2. 推荐模型搭配 <a class="header-anchor" href="#_2-推荐模型搭配" aria-label="Permalink to &quot;2. 推荐模型搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">场景需求</th><th style="text-align:left;">推荐翻译模型 (Translation)</th><th style="text-align:left;">推荐监督模型 (Supervisor)</th><th style="text-align:left;">特点与性价比</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>极致性价比 (推荐)</strong></td><td style="text-align:left;"><code>deepseek/deepseek-chat</code></td><td style="text-align:left;"><code>google/gemini-2.0-flash-001</code></td><td style="text-align:left;">速度极快，翻译地道，单集成本约 $0.005</td></tr><tr><td style="text-align:left;"><strong>极速低延迟</strong></td><td style="text-align:left;"><code>google/gemini-2.0-flash-001</code></td><td style="text-align:left;"><code>google/gemini-2.0-flash-001</code></td><td style="text-align:left;">首字响应极快，几乎零等待</td></tr><tr><td style="text-align:left;"><strong>专业文学级质感</strong></td><td style="text-align:left;"><code>anthropic/claude-3.5-haiku</code></td><td style="text-align:left;"><code>anthropic/claude-3.5-haiku</code></td><td style="text-align:left;">语境拿捏极准，修辞自然，适合高难度影视</td></tr></tbody></table><hr><h2 id="_3-在-cowatcher-中配置" tabindex="-1">3. 在 CoWatcher 中配置 <a class="header-anchor" href="#_3-在-cowatcher-中配置" aria-label="Permalink to &quot;3. 在 CoWatcher 中配置&quot;">​</a></h2><ol><li>打开 CoWatcher 扩展弹窗面板。</li><li>在 <strong>AI Service Provider</strong> 下拉菜单选择 <strong>OpenRouter</strong>。</li><li>在 <strong>OpenRouter API Key</strong> 输入框中粘贴你的密钥。</li><li>点击 <strong>Connect</strong> 按钮： <ul><li>扩展会自动向 OpenRouter 校验密钥，并动态拉取最新可用模型列表。</li><li>验证成功后状态指示卡片变为 🟢 <strong>Connected</strong>。</li></ul></li><li>在下拉列表中选择你的 <strong>Translation Model</strong> 与 <strong>Supervisor Model</strong> 即可生效。</li></ol>',12)])])}const u=t(a,[["render",n]]);export{p as __pageData,u as default};
